    for line in r:
        rows.append({k:float(v) for k,v in line.items()})
n=len(rows)
means={c:sum(x[c] for x in rows)/n for c in cols}
vars_={c:sum((x[c]-means[c])**2 for x in rows)/n for c in cols}
stds={c:math.sqrt(vars_[c]) for c in cols}
print('n',n)
for c in cols:
    print(c, 'mean', means[c], 'std', stds[c])
print('correlations')
for a in cols:
    line=[]
    for b in cols:
        cov=sum((x[a]-means[a])*(x[b]-means[b]) for x in rows)/n
        r=cov/(stds[a]*stds[b])
        line.append(f'{r:+.3f}')
    print(a, line)
