{"description":"Fit DAGs correctly with U root","cmd":"python3 - <<'PY'
import pandas as pd, numpy as np, itertools
X=pd.read_csv('/app/bn_sample_10k.csv')
cols=list(X.columns); n=len(X)
vals=X.values
col_index={c:i for i,c in enumerate(cols)}

def ll_bic(edges):
    parents={c:[] for c in cols}
    for ch,pa in edges:
        parents[ch].append(pa)
    ll=0; k=0
    for c in cols:
        pc=parents[c]
        y=vals[:,col_index[c]]
        if pc:
            A=np.column_stack([np.ones(n)]+[vals[:,col_index[p]] for p in pc])
            beta,res,rank,sv=np.linalg.lstsq(A,y,rcond=None)
            r=y-A@beta
        else:
            r=y-y.mean()
        var=np.sum(r*r)/n
        ll += -n/2*(np.log(2*np.pi*var)+1)
        k += len(pc)+2
    bic = -2*ll + k*np.log(n)
    return ll,k,bic

directed=[]
for t in cols:
    if t!='U':
        directed.append((t,'U'))  # U->t
nonU=list(set(cols)-{'U'})
for a,b in itertools.combinations(nonU,2):
    directed.append((a,b))  # b->a? (a child, b parent) => b->a
    directed.append((b,a))  # a->b
results=[]
for combo in itertools.combinations(directed,6):
    adj={c:[] for c in cols}
    ok=True
    for ch,pa in combo:
        if pa=='U' and ch!='U': pass # U parent ok
        adj[pa].append(ch)
    # ensure U has no parents: no edge with child U
    if any(ch=='U' for ch,pa in combo):
        continue
    state={}
    def dfs(v):
        state[v]=1
        for w in adj[v]:
            if state.get(w)==1: return False
            if state.get(w)==0:
                if not dfs(w): return False
        state[v]=2
        return True
    for v in cols:
        if state.get(v,0)==0:
            if not dfs(v): ok=False; break
    if not ok: continue
    ll,k,bic=ll_bic(combo)
    results.append((bic, ll, sorted(combo)))
results.sort()
print('Top 25 by BIC:')
for bic,ll,edges in results[:25]:
    estr=' '.join(f'{pa}->{ch}' for ch,pa in edges)
    print(f'BIC {bic:12.2f} LL {ll:12.2f} {estr}')
print('total',len(results))
PY"}

